function make_palindrome(string: string): string {
  const n = string.length;
  if (n === 0) return "";

  // Find the longest palindromic suffix
  let i = n - 1;
  while (i >= 0) {
    const suffix = string.slice(i);
    const reversedSuffix = suffix.split("").reverse().join("");
    if (suffix === reversedSuffix) {
      break;
    }
    i--;
  }

  // The prefix is the part before the palindromic suffix
  const prefix = string.slice(0, i + 1);
  const suffix = string.slice(i + 1);

  // Append reverse of prefix to the end
  return prefix + suffix + reversedPrefix;
}

function reversedPrefix(s: string): string {
  return s.split("").reverse().join("");
}
