function largest_prime_factor(n: number): number {
  if (n <= 1) {
    throw new Error("n must be greater than 1");
  }

  let maxFactor = 2;

  // Check for divisibility by 2
  while (n % 2 === 0) {
    maxFactor = 2;
    n /= 2;
  }

  // Check for odd factors from 3 up to sqrt(n)
  let i = 3;
  while (i * i <= n) {
    while (n % i === 0) {
      maxFactor = i;
      n /= i;
    }
    i += 2;
  }

  // If n is still greater than 1, then it is a prime factor
  if (n > 1) {
    maxFactor = n;
  }

  return maxFactor;
}
