function circular_shift(x: number, shift: number): string {
  const str = x.toString();
  const len = str.length;
  const mod = shift % len;
  if (mod === 0) return str;
  if (mod > len / 2) {
    const reversed = str.split('').reverse().join('');
    return reversed;
  }
  const shifted = str.slice(-mod) + str.slice(0, -mod);
  return shifted;
}
