function pluck(arr: number[]): number[] {
  const smallestEvenValue = Number.MAX_SAFE_INTEGER;
  const smallestEvenIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    const value = arr[i];
    if (value % 2 === 0) {
      if (value < smallestEvenValue || (value === smallestEvenValue && i < smallestEvenIndex)) {
        smallestEvenValue = value;
        smallestEvenIndex = i;
      }
    }
  }

  if (smallestEvenIndex === -1) {
    return [];
  }

  return [smallestEvenValue, smallestEvenIndex];
}
