function closest_integer(value: string): number {
  const num = parseFloat(value);
  if (isNaN(num)) {
    throw new Error("Invalid number format");
  }

  const absNum = Math.abs(num);
  const floor = Math.floor(absNum);
  const ceil = Math.ceil(absNum);

  if (absNum === floor) {
    return num;
  }

  if (absNum === ceil) {
    return num > 0 ? ceil : floor;
  }

  const diffToFloor = absNum - floor;
  const diffToCeil = ceil - absNum;

  if (diffToFloor < diffToCeil) {
    return floor;
  } else {
    return ceil;
  }
}
