function match_parens(lst: string[]): string {
  let open = 0;
  let close = 0;

  for (const s of lst) {
    if (s === '(') {
      open++;
    } else if (s === ')') {
      close++;
    }
  }

  if (open === 0 && close === 0) return 'Yes';

  if (open === 0) return 'No';
  if (close === 0) return 'No';

  if (open > close) return 'No';

  // Try to form a valid string by greedily matching
  let i = 0;
  let j = 0;
  let openCount = 0;
  let closeCount = 0;

  while (i < lst.length && j < lst.length) {
    if (lst[i] === '(') {
      openCount++;
      i++;
    } else if (lst[i] === ')') {
      closeCount++;
      i++;
    } else {
      j++;
    }
  }

  if (openCount === 0 && closeCount === 0) return 'Yes';

  if (openCount > closeCount) return 'No';

  // If we have extra open parentheses, we need to match them with the last close
  if (openCount > closeCount) {
    const lastChar = lst[lst.length - 1];
    if (lastChar === '(') return 'No';
    if (lastChar === ')') {
      const remainingOpen = openCount - closeCount;
      if (remainingOpen === 0) return 'Yes';
      return 'No';
    }
  }

  // If we have extra close parentheses, we need to match them with the first open
  if (closeCount > openCount) {
    const firstChar = lst[0];
    if (firstChar === '(') return 'No';
    if (firstChar === ')') {
      const remainingClose = closeCount - openCount;
      if (remainingClose === 0) return 'Yes';
      return 'No';
    }
  }

  return 'No';
}
