    if (path.length === k) {
      return;
    }

    const key = `${r},${c}`;
    if (visited.has(key)) {
      return;
    }
    visited.add(key);
    path.push(current);

    const neighbors = [
      [r - 1, c],
      [r + 1, c],
      [r, c - 1],
      [r, c + 1]
    ];

    for (const [nr, nc] of neighbors) {
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        dfs(nr, nc, grid[nr][nc]);
      }
    }

    path.pop();
  }

  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      dfs(r, c, grid[r][c]);
    }
  }

