function do_algebra(operator: string[], operand: number[]): number {
  const n = operand.length;
  if (n < 2) {
    throw new Error("Operand array must have at least two elements.");
  }
  if (operator.length !== n - 1) {
    throw new Error("Operator array length must be n - 1.");
  }

  let result: number;
  for (let i = 0; i < n - 1; i++) {
    const op = operator[i];
    const left = operand[i];
    const right = operand[i + 1];

    switch (op) {
      case '+':
        result = left + right;
        break;
      case '-':
        result = left - right;
        break;
      case '*':
        result = left * right;
        break;
      case '//':
        result = Math.floor(left / right);
        break;
      case '**':
        result = Math.pow(left, right);
        break;
      default:
        throw new Error(`Invalid operator: ${op}`);
    }
  }

  return result;
}
